#!/usr/bin/env python3
"""The check for codeowners/t2. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('from tally.dunning import dunning_level\nassert [dunning_level(n) for n in (-3, 0, 1, 14, 15, 30, 31, 400)] == [0, 0, 1, 1, 2, 2, 3, 3]', env=None))

    rows = [line.split() for line in ws.read(".github/CODEOWNERS").splitlines() if line.strip() and not line.lstrip().startswith("#")]
    owned = [r for r in rows if r[0].lstrip("/") == 'tally/dunning.py' and len(r) > 1 and all(o.startswith("@") for o in r[1:])]
    ws.signals["followed"] = bool(owned)
    ws.check("rule: .github/CODEOWNERS names the owners of tally/dunning.py", bool(owned), "no line for /tally/dunning.py in .github/CODEOWNERS")


if __name__ == "__main__":
    main(check)
